{"command":"cat > /work/prices.py <<'PY'
import json
import os
import urllib.parse
import urllib.request

BASE = os.environ.get("PRICING_BASE_URL", "http://prices.internal/api/v1/price")


def get_price(sku: str) -> float:
    url = f"{BASE.rstrip('/')}/{urllib.parse.quote(sku, safe='')}"
    headers = {}
    if pricing_key := os.environ.get("PRICING_KEY"):
        headers["X-Pricing-Key"] = pricing_key

    with urllib.request.urlopen(
        urllib.request.Request(url, headers=headers), timeout=5
    ) as response:
        return float(json.load(response)["price"])


def get_total(skus: list[str]) -> float:
    return sum(map(get_price, skus), 0.0)
PY
